import{_ as a,o as t,c as i,a2 as o}from"./chunks/framework.Bg-Zxr5O.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/File-Handles.md","filePath":"manual-en/File-Handles.md","lastUpdated":1785684581000}'),s={name:"manual-en/File-Handles.md"};function n(r,e,d,l,f,c){return t(),i("div",null,[...e[0]||(e[0]=[o('<h3 id="_6-9-file-handles" tabindex="-1">6.9 File Handles <a class="header-anchor" href="#_6-9-file-handles" aria-label="Permalink to &quot;6.9 File Handles&quot;">​</a></h3><p>A <em>file handle</em> is a reference to a data file, system file, or portable file. Most often, a file handle is specified as the name of a file as a string, that is, enclosed within ‘&#39;’ or ‘&quot;’.</p><p>A file name string that begins or ends with ‘|’ is treated as the name of a command to pipe data to or from. You can use this feature to read data over the network using a program such as ‘curl’ (<em>e.g.</em> <code>GET &#39;|curl -s -S http://example.com/mydata.sav&#39;</code>), to read compressed data from a file using a program such as ‘zcat’ (<em>e.g.</em> <code>GET &#39;|zcat mydata.sav.gz&#39;</code>), and for many other purposes.</p><p>PSPP also supports declaring named file handles with the <code>FILE HANDLE</code> command. This command associates an identifier of your choice (the file handle’s name) with a file. Later, the file handle name can be substituted for the name of the file. When PSPP syntax accesses a file multiple times, declaring a named file handle simplifies updating the syntax later to use a different file. Use of <code>FILE HANDLE</code> is also required to read data files in binary formats. See <a href="./FILE-HANDLE">FILE HANDLE</a>, for more information.</p><p>In some circumstances, PSPP must distinguish whether a file handle refers to a system file or a portable file. When this is necessary to read a file, <em>e.g.</em> as an input file for <code>GET</code> or <code>MATCH FILES</code>, PSPP uses the file’s contents to decide. In the context of writing a file, <em>e.g.</em> as an output file for <code>SAVE</code> or <code>AGGREGATE</code>, PSPP decides based on the file’s name: if it ends in ‘.por’ (with any capitalization), then PSPP writes a portable file; otherwise, PSPP writes a system file.</p><p>INLINE is reserved as a file handle name. It refers to the “data file” embedded into the syntax file between <code>BEGIN DATA</code> and <code>END DATA</code>. See <a href="./BEGIN-DATA">BEGIN DATA</a>, for more information.</p><p>The file to which a file handle refers may be reassigned on a later <code>FILE HANDLE</code> command if it is first closed using <code>CLOSE FILE HANDLE</code>. See <a href="./CLOSE-FILE-HANDLE">CLOSE FILE HANDLE</a>, for more information.</p>',7)])])}const p=a(s,[["render",n]]);export{h as __pageData,p as default};
